--
-- Table structure for table `attack`
--

DROP TABLE IF EXISTS `attack`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attack` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `name_pl` varchar(255) DEFAULT NULL,
  `cost` varchar(255) DEFAULT NULL,
  `damage` varchar(32) DEFAULT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `description_pl` varchar(1000) DEFAULT NULL,
  `special` tinyint(1) DEFAULT NULL,
  `rating` int DEFAULT NULL,
  `card_id` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_attack_card_id` (`card_id`),
  CONSTRAINT `fk_attack_card_id` FOREIGN KEY (`card_id`) REFERENCES `tcg_card` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26397 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

