CREATE TABLE `tcg_card` (
  `id` varchar(32) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `name_pl` varchar(255) DEFAULT NULL,
  `supertype` varchar(64) DEFAULT NULL,
  `subtypes` varchar(255) DEFAULT NULL,
  `stage` varchar(32) DEFAULT NULL,
  `hp` int DEFAULT NULL,
  `type` varchar(32) DEFAULT NULL,
  `pokedex_number` int DEFAULT NULL,
  `set_id` varchar(32) DEFAULT NULL,
  `rarity` varchar(64) DEFAULT NULL,
  `image_url_small` varchar(512) DEFAULT NULL,
  `image_url_large` varchar(512) DEFAULT NULL,
  `flavor_text` varchar(1000) DEFAULT NULL,
  `flavor_text_pl` varchar(1000) DEFAULT NULL,
  `weakness` varchar(64) DEFAULT NULL,
  `resistance` varchar(64) DEFAULT NULL,
  `retreat` int DEFAULT NULL,
  `overall_rating` int DEFAULT NULL,
  `cardmarket_url` varchar(512) DEFAULT NULL,
  `cardmarket_avg_sell_price` double DEFAULT NULL,
  `cardmarket_low_price` double DEFAULT NULL,
  `number_in_set` varchar(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_set_id` (`set_id`),
  CONSTRAINT `fk_set_id` FOREIGN KEY (`set_id`) REFERENCES `card_set` (`id`)
